import{z as n,x as p,o as t,c as B,q as s,j as r,D as E,d as C,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"DCTCP","description":"","frontmatter":{"title":"DCTCP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dctcp.md","filePath":"cs/dctcp.md","lastUpdated":1791063341000}'),d={name:"cs/dctcp.md"};function A(c,a,h,D,T,P){const l=p("Mermaid");return t(),B("div",null,[a[2]||(a[2]=s('<h1 id="dctcp" tabindex="-1">DCTCP <a class="header-anchor" href="#dctcp" aria-label="Permalink to &quot;DCTCP&quot;">​</a></h1><div class="epigraph"><p>交换机在浅阈标记 CE，发送方用标记比例做乘性减，把队列维持在小深度，换 incast 存活与低延迟。</p><footer>—— 据 Alizadeh et al., DCTCP, SIGCOMM 2010；RFC 8257 整理</footer></div><p><a href="/cs/incast">上一课</a> 要更早的信号。<a href="/cs/tcp-congestion">拥塞控制</a> 的丢包信号太晚。缺口是 <strong>DCTCP</strong>：ECN 比例反馈，不是等丢。本课不把 RoCE 无损写完。主干 ECN 细节在后课传输单元再钉一次，这里只收数据中心缺口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Reno/CUBIC 看到丢才减半，队列已满。DCTCP：RED/阈上标 CE，不丢；发送方估计标记分数 \\(\\alpha\\)，每 RTT 把窗口乘 \\((1-\\alpha/2)\\)。稳态队列贴着阈，缓冲可浅，incast 时仍有空位。与广域 CUBIC 混跑会不公平——数据中心常隔离。</p><p><span class="marginnote">术语翻译：ECN（显式拥塞通知）是交换机在丢包之前「打手势」的手段——在包头上标一个 CE（拥塞经历）记号而不是把包丢掉；发送方数一数被标记的比例，就知道网络挤到了什么程度。</span></p><p>不要把 DCTCP 写成 BBR：一个用 ECN 比例，一个用带宽时延模型。</p><p><span class="marginnote">RFC 8257。需要端与交换机都开 ECN。本课不调 \\(\\alpha\\) 的 EWMA 系数考试。</span></p><h3 id="标记比例减窗" tabindex="-1">标记比例减窗 <a class="header-anchor" href="#标记比例减窗" aria-label="Permalink to &quot;标记比例减窗&quot;">​</a></h3><p>浅阈维持小队列，服务 incast 与尾延迟。需全程 ECN。与公网 CUBIC 混跑不公平。不提高口速 \\(C\\)。</p><p><span class="marginnote">数字实例：一个 RTT 发 100 个包、其中 10 个被标 CE，则 \\(\\alpha=0.1\\)，窗口乘 \\((1-0.1/2)=0.95\\)，只减 5%；对比传统 TCP 丢一个包直接减半 50%。减窗幅度跟着拥塞程度走，队列才能稳在浅深度而不是锯齿状深浅震荡。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：丢包减半 vs 标记比例减。画：队列 ≥ 阈 → CE → 收端回 ECE → 发端调 \\(\\alpha\\)。Clos 每跳都可标，信号是路径上最挤的那一跳。</p>',13)),(t(),r(i,null,{default:E(()=>[o(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20TH%5B%22%E6%B5%85%E9%98%88%22%5D%20--%3E%20CE%5B%22%E6%A0%87%20CE%22%5D%0A%20%20CE%20--%3E%20ECE%5B%22ACK%20%E5%B8%A6%E5%9B%9E%22%5D%0A%20%20ECE%20--%3E%20ALP%5B%22%E4%BC%B0%E8%AE%A1%20alpha%22%5D%0A%20%20ALP%20--%3E%20WIN%5B%22%E7%AA%97%E5%8F%A3%201-alpha%2F2%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[C(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[C("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"PFC 与 DCTCP 可叠：无损给无丢语义，DCTCP 管队列深度。仅 PFC 会把拥塞停到网边。容量仍由口速决定；DCTCP 提高的是浅缓冲下的有效吞吐与尾延迟。P4 可自定义标记，不改概念。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为 DCTCP 能把网络「变快」。它不提高链路口速 \\(C\\)——容量上限还是交换机决定的；它提高的是浅缓冲下的有效吞吐和尾延迟，即同样跑得快的同时排队更短、最坏情况更可控。")],-1)),(t(),r(i,null,{default:E(()=>[o(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%98%9F%E5%88%97%E8%B6%8A%E8%BF%87%E7%9A%84%E4%BF%A1%E5%8F%B7%E5%87%BA%E7%8E%B0%22%5D%20--%3E%20CUBIC%5B%22CUBIC%EF%BC%9A%E7%AD%89%E4%B8%A2%E5%8C%85%E6%89%8D%E5%8F%8D%E5%BA%94%22%5D%0A%20%20CUBIC%20--%3E%20DQ%5B%22%E9%98%9F%E5%88%97%E5%85%88%E8%A2%AB%E5%A1%AB%E6%BB%A1%EF%BC%8C%E5%BB%B6%E8%BF%9F%E9%A3%99%E5%8D%87%22%5D%0A%20%20Q%20--%3E%20DCT%5B%22DCTCP%EF%BC%9A%E8%BF%87%E6%B5%85%E9%98%88%E7%AB%8B%E5%88%BB%E6%A0%87%20CE%22%5D%0A%20%20DCT%20--%3E%20ALP%5B%22%E6%8C%89%E6%A0%87%E8%AE%B0%E6%AF%94%E4%BE%8B%20alpha%20%E5%BE%AE%E5%87%8F%22%5D%0A%20%20ALP%20--%3E%20SQ%5B%22%E9%98%9F%E5%88%97%E8%B4%B4%E7%9D%80%E6%B5%85%E9%98%88%E7%A8%B3%E4%BD%8F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[C(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p>短流可能在窗口起来前结束，主要受益是长流与同步扇入。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 DCQCN 的全部。RoCE 与无损网络是下一课。后课默认：DCTCP 用 ECN 比例维持浅队列，服务数据中心。</p><p>互联网核心不假设 DCTCP 邻居，故不作为公网默认。</p><p>下一课<a href="/cs/roce-lossless">RoCE 与无损网络</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>标记比例替代丢包减半，队列浅。</li><li>需全程 ECN；与 CUBIC 混跑不公平。</li><li>针对 incast 与尾延迟，不提高 \\(C\\)。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Alizadeh et al., 2010；RFC 8257。</li></ul>',7))])}const u=n(d,[["render",A]]);export{f as __pageData,u as default};
